import React, { useState } from 'react';
import { MessageSquare, PhoneCall, Shield, Bot, CheckCircle2, Sparkles } from 'lucide-react';

export default function FeatureCards() {
  const [activeTab, setActiveTab] = useState(0);

  const features = [
    {
      id: 0,
      icon: MessageSquare,
      title: 'Instant Messaging',
      desc: 'Real-time text, voice notes, media sharing with typing indicators and read receipts.',
      detail: 'Enjoy sub-10ms delivery speed, reaction emojis, rich media previews, and auto-sync across mobile and web.',
      color: 'from-sky-500 to-blue-600'
    },
    {
      id: 1,
      icon: PhoneCall,
      title: 'HD Voice & Video Calls',
      desc: 'Crystal-clear audio and 4K video calls with noise cancellation & screen sharing.',
      detail: 'Powered by WebRTC with dynamic bitrate adaptation to ensure clear audio even on weak networks.',
      color: 'from-cyan-500 to-sky-600'
    },
    {
      id: 2,
      icon: Shield,
      title: 'End-to-End Security',
      desc: 'Military-grade 256-bit encryption ensuring complete privacy for all messages & calls.',
      detail: 'Zero data logging, self-destructing messages, and biometric lock verification.',
      color: 'from-emerald-500 to-teal-600'
    },
    {
      id: 3,
      icon: Bot,
      title: 'Smart Automation',
      desc: 'Automated quick replies, chatbot workflows, and business scheduling tools.',
      detail: 'Integrate custom AI assistants and auto-responders to engage your audience 24/7.',
      color: 'from-indigo-500 to-sky-600'
    }
  ];

  return (
    <section className="py-20 bg-white border-t border-slate-100">
      <div className="max-w-7xl mx-auto px-6 sm:px-8 lg:px-12">
        {/* Section Header */}
        <div className="text-center max-w-2xl mx-auto space-y-4 mb-16">
          <div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-sky-50 border border-sky-100 text-sky-700 text-xs font-semibold">
            <Sparkles className="w-3.5 h-3.5" />
            <span>Interactive Features</span>
          </div>
          <h2 className="text-3xl sm:text-4xl font-extrabold text-slate-900 tracking-tight">
            Designed for Live Experience
          </h2>
          <p className="text-base text-slate-600">
            Explore how Connect elevates daily communication with speed, intelligence, and security.
          </p>
        </div>

        {/* Feature Cards Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {features.map((item) => {
            const Icon = item.icon;
            const isActive = activeTab === item.id;
            return (
              <div
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`group relative p-6 rounded-3xl border transition-all duration-300 cursor-pointer ${
                  isActive
                    ? 'bg-slate-900 text-white border-slate-900 shadow-xl shadow-slate-900/10 scale-[1.02]'
                    : 'bg-white text-slate-800 border-slate-200/70 hover:border-sky-300 hover:shadow-lg hover:-translate-y-1'
                }`}
              >
                <div
                  className={`w-12 h-12 rounded-2xl flex items-center justify-center mb-6 transition-all duration-300 ${
                    isActive
                      ? 'bg-sky-500 text-white shadow-md'
                      : 'bg-sky-50 text-sky-600 group-hover:bg-[#006699] group-hover:text-white'
                  }`}
                >
                  <Icon className="w-6 h-6" />
                </div>

                <h3 className={`text-lg font-bold mb-2 ${isActive ? 'text-white' : 'text-slate-900'}`}>
                  {item.title}
                </h3>

                <p className={`text-xs leading-relaxed ${isActive ? 'text-slate-300' : 'text-slate-500'}`}>
                  {item.desc}
                </p>

                {isActive && (
                  <div className="mt-4 pt-4 border-t border-slate-800 text-[11px] text-sky-400 font-medium animate-in fade-in duration-300 flex items-center gap-1.5">
                    <CheckCircle2 className="w-4 h-4 shrink-0 text-emerald-400" />
                    <span>{item.detail}</span>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
